def quick_sort(arr: list[int]) -> list[int]:
    def partition(lo: int, hi: int) -> int:
        pivot = arr[lo]
        i = lo
        for j in range(lo + 1, hi + 1):
            if arr[j] < pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[lo], arr[i] = arr[i], arr[lo]
        return i

    def sort(lo: int, hi: int) -> None:
        if lo >= hi:
            return
        p = partition(lo, hi)
        sort(lo, p - 1)
        sort(p + 1, hi)

    sort(0, len(arr) - 1)
    return arr

